import java.util.*;

class Solution {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String root;
    }

    public String replaceWords(List<String> dictionary, String sentence) {
        TrieNode trieRoot = new TrieNode();
        for (String root : dictionary) {
            insert(trieRoot, root);
        }

        String[] words = sentence.split(" ");
        for (int i = 0; i < words.length; i++) {
            words[i] = shortestRoot(trieRoot, words[i]);
        }
        return String.join(" ", words);
    }

    private void insert(TrieNode trieRoot, String root) {
        TrieNode node = trieRoot;
        for (char c : root.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new TrieNode();
            }
            node = node.children[idx];
        }
        if (node.root == null || root.length() < node.root.length()) {
            node.root = root;
        }
    }

    private String shortestRoot(TrieNode trieRoot, String word) {
        TrieNode node = trieRoot;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                return word;
            }
            node = node.children[idx];
            if (node.root != null) {
                return node.root;
            }
        }
        return word;
    }
}

import java.util.*;

class Solution {
    private static class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        String root;
    }

    public String replaceWords(List<String> dictionary, String sentence) {
        TrieNode trieRoot = new TrieNode();
        for (String root : dictionary) {
            TrieNode node = trieRoot;
            for (char c : root.toCharArray()) {
                node = node.children.computeIfAbsent(c, key -> new TrieNode());
            }
            if (node.root == null || root.length() < node.root.length()) {
                node.root = root;
            }
        }

        String[] words = sentence.split(" ");
        for (int i = 0; i < words.length; i++) {
            words[i] = findRoot(trieRoot, words[i]);
        }
        return String.join(" ", words);
    }

    private String findRoot(TrieNode trieRoot, String word) {
        TrieNode node = trieRoot;
        for (char c : word.toCharArray()) {
            node = node.children.get(c);
            if (node == null) {
                return word;
            }
            if (node.root != null) {
                return node.root;
            }
        }
        return word;
    }
}

import java.util.*;

class Solution {
    public String replaceWords(List<String> dictionary, String sentence) {
        Set<String> roots = new HashSet<>(dictionary);
        String[] words = sentence.split(" ");
        for (int i = 0; i < words.length; i++) {
            words[i] = replacement(roots, words[i]);
        }
        return String.join(" ", words);
    }

    private String replacement(Set<String> roots, String word) {
        for (int end = 1; end <= word.length(); end++) {
            String prefix = word.substring(0, end);
            if (roots.contains(prefix)) {
                return prefix;
            }
        }
        return word;
    }
}

import java.util.*;

class Solution {
    public String replaceWords(List<String> dictionary, String sentence) {
        List<String> roots = new ArrayList<>(dictionary);
        roots.sort(Comparator.comparingInt(String::length));

        String[] words = sentence.split(" ");
        for (int i = 0; i < words.length; i++) {
            for (String root : roots) {
                if (words[i].startsWith(root)) {
                    words[i] = root;
                    break;
                }
            }
        }
        return String.join(" ", words);
    }
}
